<?php $e = static fn (mixed $value): string => App\Core\View::e($value); ?>
<section>
    <div class="section-heading"><div><p class="eyebrow">Conteudo editorial</p><h1>Noticias</h1><p>Gerencie noticias por campeonato.</p></div><a class="button" href="<?= $e(App\Core\Config::url('/admin/noticias/novo')) ?>">Nova noticia</a></div>
    <?php if (!empty($message)): ?><p class="success"><?= $e($message) ?></p><?php endif; ?>
    <form class="filter-bar" method="get" action="<?= $e(App\Core\Config::url('/admin/noticias')) ?>"><label>Busca <input name="q" value="<?= $e($filters['q'] ?? '') ?>"></label><label>Status <select name="status"><option value="">Todos</option><?php foreach ($statuses as $status): ?><option value="<?= $e($status) ?>" <?= ($filters['status'] ?? '') === $status ? 'selected' : '' ?>><?= $e($status) ?></option><?php endforeach; ?></select></label><label>Campeonato <select name="championship_id"><option value="">Todos</option><?php foreach ($championships as $championship): ?><option value="<?= (int) $championship['id'] ?>" <?= (string) ($filters['championship_id'] ?? '') === (string) $championship['id'] ? 'selected' : '' ?>><?= $e($championship['name']) ?></option><?php endforeach; ?></select></label><button type="submit">Filtrar</button></form>
    <div class="table-wrap"><table><thead><tr><th>Titulo</th><th>Campeonato</th><th>Status</th><th>Publicacao</th><th>Autor</th><th>Acoes</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><a href="<?= $e(App\Core\Config::url('/admin/noticias/' . $item['id'])) ?>"><?= $e($item['title']) ?></a><?= !empty($item['featured']) ? ' <strong>Destaque</strong>' : '' ?></td><td><?= $e($item['championship_name']) ?></td><td><?= $e($item['status']) ?></td><td><?= $e($item['published_at'] ?: '-') ?></td><td><?= $e($item['author_name']) ?></td><td><a href="<?= $e(App\Core\Config::url('/admin/noticias/' . $item['id'] . '/editar')) ?>">Editar</a></td></tr><?php endforeach; ?><?php if (!$items): ?><tr><td colspan="6">Nenhuma noticia encontrada.</td></tr><?php endif; ?></tbody></table></div>
    <?php if ($pages > 1): ?><nav class="pagination" aria-label="Paginacao"><?php for ($index = 1; $index <= $pages; $index++): ?><a class="<?= $index === $page ? 'active' : '' ?>" href="<?= $e(App\Core\Config::url('/admin/noticias?page=' . $index . '&q=' . urlencode($filters['q'] ?? '') . '&status=' . urlencode($filters['status'] ?? '') . '&championship_id=' . urlencode($filters['championship_id'] ?? ''))) ?>"><?= $index ?></a><?php endfor; ?></nav><?php endif; ?>
</section>
